def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n >= 95:
        return 'D'

    me_last, opp_last = history[-1]

    my_d = 0
    opp_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    if opp_last == 'D':
        if me_last == 'D':
            if opp_d / n > 0.5:
                return 'D'
            else:
                return 'C'
        else:
            my_recent_d = 0
            start = max(0, n - 3)
            for i in range(start, n):
                if history[i][0] == 'D':
                    my_recent_d += 1
            if my_recent_d > 0:
                return 'C'
            if opp_d / n < 0.3:
                return 'C'
            return 'D'
    else:
        if me_last == 'D':
            if opp_d == 0:
                return 'D'
            else:
                return 'C'
        else:
            if my_d == 0 and n >= 10:
                streak_c = 0
                for i in range(n - 1, -1, -1):
                    if history[i][0] == 'C' and history[i][1] == 'C':
                        streak_c += 1
                    else:
                        break
                if streak_c >= 10:
                    return 'D'
            return 'C'
